package ociresources

import (
	"errors"
	"fmt"
	"net/url"
	"slices"
	"sort"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/engine"
	"github.com/anthnel/devdesk/internal/imagesearch"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// → at level 1 (DEVDESK-304, IS-08): it opens the tags of the row under the
// cursor, on that row's registry only, with the row's final repository as is.
// No test reaches a registry: the listRegistryTags seam answers, and the Cmd
// the handler returns for Hub metadata is never run.

// withEngine installs name as the current engine for the test.
func withEngine(t *testing.T, name string) {
	t.Helper()
	previous := engine.Current()
	t.Cleanup(func() { engine.SetCurrent(previous) })
	engine.SetCurrent(engine.ShapeFor(name))
}

// drillRows is level 1 settled with an `nginx` row on each registry of
// testConfig: "prod" (registry.example.com) and "hub" (docker.io, whose final
// repository carries library/).
func drillRows(t *testing.T) Model {
	t.Helper()
	m := lvl1SearchingModel(t)
	return feed(t, m,
		ImageSearchResultMsg{Gen: m.registryBrowser.gen, EntryKey: "prod",
			Images: []imagesearch.Image{{Name: "nginx", Repo: "nginx"}}},
		ImageSearchResultMsg{Gen: m.registryBrowser.gen, EntryKey: "hub",
			Images: []imagesearch.Image{{Name: "nginx", Repo: "library/nginx"}}},
	)
}

// selectImage moves the level 1 cursor to the row of (entryKey, repo).
func selectLevelOneRow(t *testing.T, m Model, entryKey, repo string) Model {
	t.Helper()
	m = feed(t, m, testutil.Key("home"))
	for range len(m.registryBrowser.searchTable.Visible()) + 1 {
		if r, ok := m.registryBrowser.searchTable.Selected(); ok && r.img.EntryKey == entryKey && r.img.Repo == repo {
			return m
		}
		m = feed(t, m, testutil.Key("down"))
	}
	t.Fatalf("no level 1 row for %s %s", entryKey, repo)
	return m
}

// pressRight presses → and plays the tag answers back into the model.
func pressRight(t *testing.T, m Model) (Model, tea.Cmd, []MultiRegistryTagsLoadedMsg) {
	t.Helper()
	m, cmd := step(t, m, testutil.Key("right"))
	var loaded []MultiRegistryTagsLoadedMsg
	for _, msg := range testutil.Msgs(cmd) {
		if l, ok := msg.(MultiRegistryTagsLoadedMsg); ok {
			loaded = append(loaded, l)
		}
	}
	for _, l := range loaded {
		m = feed(t, m, l)
	}
	return m, cmd, loaded
}

func tagRefs(m Model) []string {
	var out []string
	for _, tag := range m.registryBrowser.tags {
		out = append(out, multiImageName(tag.RegistryURL, tag.Repo, tag.Tag))
	}
	sort.Strings(out)
	return out
}

func (r *fullTagCalls) reset() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.calls = nil
}

// c.1: one request, to the row's registry, with the row's repository.
func TestRightOpensTheTagsOfTheSelectedRowOnly(t *testing.T) {
	withEngine(t, engine.Docker)
	rec := withFullTagRecorder(t)
	m := selectLevelOneRow(t, drillRows(t), "hub", "library/nginx")

	m, _, loaded := pressRight(t, m)

	b := m.registryBrowser
	if b.state != browserStateTags {
		t.Fatalf("state = %d, want browserStateTags", b.state)
	}
	if !b.tagsFromSearch {
		t.Error("tagsFromSearch is false after →")
	}
	m := lvl1ImagesModel(t)
	m.registryBrowser.searcher = nil
	if strings.Contains(registryBrowserHelp(t, m), "→") {
		t.Error("help without a Searcher mentions →")
	}
}

// ── failure after → ─────────────────────────────────────────────────────────

// afterRight presses → on the hub row (nothing is run) and returns the model.
func afterRight(t *testing.T) Model {
	t.Helper()
	withFullTagRecorder(t)
	m, _ := step(t, selectLevelOneRow(t, drillRows(t), "hub", "library/nginx"), testutil.Key("right"))
	return m
}

func failedTags(m Model, err error) MultiRegistryTagsLoadedMsg {
	return MultiRegistryTagsLoadedMsg{
		Gen: m.registryBrowser.gen, EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub",
		Repo: "library/nginx", Err: err,
	}
}

func TestTagsFailingAfterRightShowAnErrorAndKeepTheTable(t *testing.T) {
	m := afterRight(t)

	m, cmd := step(t, m, failedTags(m, errors.New("boom")))

	if m.registryBrowser.state != browserStateTags {
		t.Fatalf("state = %d, want browserStateTags", m.registryBrowser.state)
	}
	if got := len(m.registryBrowser.tagTable.Items()); got != 0 {
		t.Errorf("tag rows = %d, want 0", got)
	}
	view := ansi.Strip(m.registryBrowser.View())
// "/" is a search, but only when a Searcher is injected (defaultImageSearcher
// is nil in production, Q1 option A); a name with a "/" stays the tag flow.

// fakeSearcher records every call and answers one image per call.
type fakeSearcher struct {
	mu      sync.Mutex
	targets []imagesearch.Target
	queries []imagesearch.Query
	ctxs    []context.Context
}

func (f *fakeSearcher) Search(ctx context.Context, t imagesearch.Target, q imagesearch.Query) ([]imagesearch.Image, bool, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.targets = append(f.targets, t)
	f.queries = append(f.queries, q)
	f.ctxs = append(f.ctxs, ctx)
	return []imagesearch.Image{{EntryKey: t.EntryKey, Name: q.Text, Repo: q.Text}}, false, nil
}

func (f *fakeSearcher) calls() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.targets)
}

func (f *fakeSearcher) keys() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]string, 0, len(f.targets))
	for _, t := range f.targets {
		out = append(out, t.EntryKey)
	}
	sort.Strings(out)
	return out
}

// withImageSearcher injects s for the test. Call it BEFORE opening the
// browser: newRegistryBrowser reads defaultImageSearcher.
func withImageSearcher(t *testing.T, s imagesearch.Searcher) {
	t.Helper()
	prev := defaultImageSearcher
	defaultImageSearcher = s
	t.Cleanup(func() { defaultImageSearcher = prev })
}

// tagCalls swaps the listRegistryTags seam for a recorder of (apiURL, repo).
type tagCalls struct {
	mu    sync.Mutex
	repos []string
}

func withTagRecorder(t *testing.T) *tagCalls {
	t.Helper()
	r := &tagCalls{}
	prev := listRegistryTags
	listRegistryTags = func(_ context.Context, _, repo, _, _ string) ([]string, error) {
		r.mu.Lock()
		defer r.mu.Unlock()
		r.repos = append(r.repos, repo)
		return []string{"v1"}, nil
	}
	t.Cleanup(func() { listRegistryTags = prev })
	return r
}

func (r *tagCalls) sorted() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := append([]string(nil), r.repos...)
	sort.Strings(out)
	return out
}

func checkedKeys(m Model) []string {
	var out []string
	for _, e := range m.registryBrowser.entries {
		if m.registryBrowser.selected(e) {
			out = append(out, e.key)
		}
	}
	sort.Strings(out)
	return out
}

func sameStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func submitRaw(t *testing.T, m Model, text string) (Model, tea.Cmd) {
	t.Helper()
	m = typeInto(t, m, text)
	return step(t, m, testutil.Key("enter"))
// fullTagCall is one request the tag lookup sent to a registry.
type fullTagCall struct{ apiURL, repo, user, pass string }

type fullTagCalls struct {
	mu    sync.Mutex
	calls []fullTagCall
}

// withFullTagRecorder swaps the listRegistryTags seam for a recorder of every
// argument that reaches the registry (withTagRecorder keeps only the repo).
func withFullTagRecorder(t *testing.T) *fullTagCalls {
	t.Helper()
	r := &fullTagCalls{}
	prev := listRegistryTags
	listRegistryTags = func(_ context.Context, apiURL, repo, user, pass string) ([]string, error) {
		r.mu.Lock()
		defer r.mu.Unlock()
		r.calls = append(r.calls, fullTagCall{apiURL, repo, user, pass})
		return []string{"v1", "latest"}, nil
	}
	t.Cleanup(func() { listRegistryTags = prev })
	return r
}

// sorted returns the calls as strings, in a stable order.
func (r *fullTagCalls) sorted() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]string, 0, len(r.calls))
	for _, c := range r.calls {
		out = append(out, fmt.Sprintf("%q", []string{c.apiURL, c.repo, c.user, c.pass}))
	}
	sort.Strings(out)
	return out
}

func (r *fullTagCalls) repos() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]string, 0, len(r.calls))
	for _, c := range r.calls {
// arrival of results; this file covers what the user does once it is open.

// groupedModel returns a browser whose first registry resolved into a group of
// two members, so the entry list mixes members and a plain registry.
func groupedModel(t *testing.T) Model {
	t.Helper()
	m := feed(t, loadedModel(t), RegistryGroupCacheLoadedMsg{Entries: groupCacheFixture()})
	return feed(t, m, testutil.Key(keymap.Browser))
}

func typeInto(t *testing.T, m Model, s string) Model {
	t.Helper()
	return feed(t, m, testutil.Type(s)...)
}

// resultsModel returns a browser on its results screen, having actually
// submitted a search. searchedModel feeds tags in without submitting, which is
// enough to test where results land but leaves the browser on the form — the
// results table is only rebuilt while the tags screen is showing.
func resultsModel(t *testing.T, msgs ...tea.Msg) Model {
	t.Helper()

	m := typeInto(t, browsingModel(t), "api")
	m = feed(t, m, testutil.Key("enter"))
	if m.registryBrowser.state != browserStateTags {
		t.Fatalf("the search did not reach the results screen (state %d)", m.registryBrowser.state)
	}
