	f.mu.Lock()
	defer f.mu.Unlock()
	f.targets = append(f.targets, t)
	f.queries = append(f.queries, q)
	f.ctxs = append(f.ctxs, ctx)
	return []imagesearch.Image{{EntryKey: t.EntryKey, Name: q.Text, Repo: q.Text}}, false, nil
}

